from itertools import permutations

def is_continuous(f, tau_X, tau_Y):
    """True if every preimage under the dict f of a set in tau_Y is in tau_X."""
    opens = set(tau_X)
    for V in tau_Y:
        if frozenset(x for x in f if f[x] in V) not in opens:
            return False
    return True

def are_homeomorphic(X, tau_X, Y, tau_Y):
    """True if some bijection X -> Y carries tau_X onto tau_Y."""
    xs, ys = sorted(X), sorted(Y)
    if len(xs) != len(ys):
        return False
    target = set(tau_Y)
    for perm in permutations(ys):
        m = dict(zip(xs, perm))
        if {frozenset(m[x] for x in U) for U in tau_X} == target:
            return True
    return False
